{
  "morphology_wrong_forms": [
    {
      "wrong_form": "无量地",
      "explanation": "无量 is typically used as a stative adjective or in fixed Buddhist/literary compounds, not as an adverbial modifier taking 地."
    },
    {
      "wrong_form": "无量化",
      "explanation": "Suffixing 化 turns a noun into a process/verb (like 现代化), but 无量 is an abstract property of scale that cannot be a process."
    },
    {
      "wrong_form": "无量们",
      "explanation": "The plural suffix 们 is exclusively used for human or animate personal nouns, whereas 无量 describes abstract quantities."
    }
  ],
  "l1_audio_confusables": [
    {
      "confusable_word": "力量",
      "explanation": "Similar second syllable and vowel sounds (liàng vs liáng), but means 'strength/power' instead of 'boundless'."
    },
    {
      "confusable_word": "流量",
      "explanation": "Shares the '-liàng' ending, commonly confused by learners mishearing initial consonants (wú vs liú)."
    },
    {
      "confusable_word": "重量",
      "explanation": "Also ends in liàng, which can sound phonetically similar in fast speech compared to wūliàng."
    }
  ],
  "collocation_distractors": [
    {
      "distractor": "狭窄",
      "explanation": "Means 'narrow'. It directly contradicts the meaning of 无量 (boundless/immeasurable)."
    },
    {
      "distractor": "有限",
      "explanation": "Means 'limited'. This is an antonym, making it an incorrect collocation for a word denoting infinity."
    },
    {
      "distractor": "短暂",
      "explanation": "Means 'brief/short-lived'. It clashes with the vast spatial or temporal scale implied by 无量."
    }
  ],
  "collocation_wrong_collocate": {
    "target_base": "前途",
    "planted_wrong": "深厚",
    "explanation": "前途 (future/prospects) collocates with 无量 to mean 'boundless prospects', but learners mistakenly use 深厚 (deep/profound)."
  },
  "cloze_distractors": [
    {
      "option": "大量",
      "explanation": "Means 'large quantity/a lot'. While related to amount, it lacks the mystical or absolute magnitude of 无量."
    },
    {
      "option": "过量",
      "explanation": "Means 'excessive'. This carries a negative connotation of having too much, unlike the neutral or positive tone of 无量."
    },
    {
      "option": "尽量",
      "explanation": "An adverb meaning 'to the best of one's ability', chosen purely due to superficial visual similarity in characters."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "这家超市的商品无量，什么都有。",
      "wrong_reason": "无量 cannot be used to describe physical commercial inventory in a mundane supermarket setting; use 丰富 instead."
    },
    {
      "sentence": "今天跑完步后，我感到无量的疲惫。",
      "wrong_reason": "Physical fatigue is countable or measurable in degree, whereas 无量 is reserved for abstract, infinite scopes like 前途 or 功德."
    },
    {
      "sentence": "这栋大楼的高度无量，直插云霄。",
      "wrong_reason": "Architectural height is concrete and measurable; 无量 cannot replace adjectives like 无限 or 极高 for physical heights."
    }
  ],
  "spot_incorrect": {
    "sentence": "他的未来前途无量着，必定能成功。",
    "planted_error": "着",
    "error_description": "前途无量 is a complete set phrase functioning as a predicate; adding the continuous aspect marker 着 is ungrammatical.",
    "corrected_version": "他的未来前途无量，必定能成功。"
  },
  "word_family_fake_forms": [
    "无度量",
    "无计量",
    "无超量"
  ],
  "particle_candidates": []
}
